import{_ as a,c as e,o as r,af as t}from"./chunks/framework.zX5h-Rkw.js";const l=JSON.parse('{"title":"南武朋克 第四章","description":"","frontmatter":{},"headers":[],"relativePath":"archives_n_arts/arts/nambu_punk/4.md","filePath":"archives_n_arts/arts/nambu_punk/4.md"}'),_={name:"archives_n_arts/arts/nambu_punk/4.md"};function n(s,p,o,c,h,i){return r(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="南武朋克-第四章" tabindex="-1">南武朋克 第四章 <a class="header-anchor" href="#南武朋克-第四章" aria-label="Permalink to “南武朋克 第四章”">​</a></h1><p>第一次参与“零光”的集会，我按照约定来到了指定场所，用是一家肠粉店。该店隐藏在一簇自供给式居民聚集片区（即旧世界时说的“城中村”“棚户区”）的中枢性交易交通干道的一角。走进该干道百余米，左侧一栋二层暗粉色小楼的楼面店铺便是其所在地。黄底红字招牌，玻璃店门，店内的简易木制食客椅——足够寻常、不起眼，太棒了，“就像百千棵树上的百千个鸟窝”。</p><p>“来份‘双蛋肉蛋肠’。”，按照约定好的口令，我对在隔间忙活的老阿姨说。</p><p>“楼上。”，她转过身，指向隔间隔壁的水泥楼梯，又转回去继续忙活。</p><p>走上楼去、是一间杂物房，杂乱堆放的食材纸箱堆放在一套餐桌周围，墙上开了扇小窗，阳光懒洋洋地洒进房间，能看见光柱中风飞的尘埃。</p><hr><p>“坐。”唐人招呼我，身旁坐着一男一女。</p><p>于是我坐下，每人面前都是一碟肠粉。</p><p>“先吃吧，吃点好的。”</p><p>肠粉上浇着豉油，混有鸡蛋的透亮粉皮隐约能看出粉色的肉片。</p><p>我夹起一块，送入嘴中，粉皮嫩滑，鸡蛋香浓，豉油浸润在粉皮中，带来柔顺口感，爽脆的嫩肉肉汁清甜，难道是真肉？！</p><p>“我擦，太好吃了！”，我发自内心地呐喊。</p><p>我狼吞虎咽地品着，不一会儿，碟子里只剩下几滴酱汁。</p><hr><p>“吃完了吗？我们开始吧。”</p><p>“这是真肉吗？太香了。”</p><p>“哪还吃得上真肉呀，不过，好吃吧？”我大力点头。</p><p>“说回正题。”唐人清清噪子，将手搭在一旁的男生肩上。男生的身材恰好与唐人形成反衬，精瘦修长，发型爽朗，五官清晰，“我是堇”他说。</p><p>“堇是原来负责外联工作的人，但是他也懂一部分技术，能指导与协调小组工作。” ，“情况就是这样。”堇看着我。</p><p>唐人转过头，“这位是小雅。”</p><p>是她。我见她的第一面。</p><hr><p>又回忆起她了，我忍不住一阵心痛，心绞痛。</p><p>雅，要是没见过你，不曾认识你，我们会有不同的人生轨迹罢。</p><p>“我们的终端”，我望着终端，一滴泪水滴落在桌面上。</p><hr><p>那天她一头爽朗的短发，左侧别着个笑脸发夹。明明是炎热的九月，可她却让我永远留在善感的春季四月天。</p><p>她画看清妆，精致小巧的五官，傲娇的鼻子，鼻子下一颗Q弹的圣女果，好想狠狠地吮吸，灵动大眼里那汪极清澈的蔚蓝潭水，无论何时都不能扰起波纹；她穿着T恤背带裤，胸部起伏着，并不算大，个子也苗条娇小，但个头不矮。</p><p>“你好。”她这么一叫我，我才从直勾勾地看着她中复苏，心中一阵悸动。那时我作为一介处男，过着压抑的学院生话，而这惊鸿一督却让我被雪藏的青着苏醒，“一见钟情大概也就这样吧“。</p><hr><p>唐人继续介绍，“她是零光年少有为的安全学专家，你进组以后，技术这方面主要是与她打交道。”</p><p>“好。”，我答。“还有什么疑惑吗？”</p><p>我看看她，她微笑地看着我；我又看看堇，他也微笑着。</p><p>“......为什么选中我？”，“组织决定的，也就是The Chosen One。”</p><p>“我有什么任务吗，不能光闲着，额。得做点什么，对吧？”</p><p>“组织上会安排的，别太拘束，他忽而站起身，走到我身后，双手捏了捏我肩，“放松点儿。”</p><p>那是一双温暖厚重的手掌，未经义体化改造。</p><p>堇也说，“今后你也是我们的一员了，欢迎你。”</p><p>堇是个版正的男生，做事沉稳，而且敢于行动。</p><p>“那么咱以后怎么联系？”，“已经联系上了，不是吗？”，唐人即答。</p><p>“为什么你叫唐人？”，他稍作沉思，“因为我是一名唐人。”</p><p>我实在是理解不能，唐人、唐朝，似乎只是存在于什么架空世界历史小说中的概念吧。</p><hr><p>那天回到宿舍后，洗过澡，我躺在床上，“今天真是充实”。</p><p>宿友都是优秀的“进步者”们的子弟，且对芯片都没有排异反应。我有点感慨，但是又不能表现出来，只能憋在心里。“为你们悲哀，真的。”</p>',45)])])}const m=a(_,[["render",n]]);export{l as __pageData,m as default};
